type Listing = { id: string; price: number; location: string; rooms: number }

export function filterListings(listings: Listing[], q: { min?: number; max?: number; rooms?: number }) {
  return listings.filter((l) => {
    if (q.min != null && l.price < q.min) return false
    if (q.max != null && l.price > q.max) return false
    if (q.rooms != null && l.rooms !== q.rooms) return false
    return true
  })
}

const cache = new Map<string, unknown>()

export function cachedFilter<T>(key: string, compute: () => T): T {
  if (cache.has(key)) return cache.get(key) as T
  const value = compute()
  cache.set(key, value)
  return value
}
